PRODUCTION_SOURCE = '"""\nOLA-049\nOracle OLA-030 Lineage Graph Integration Adapter\n\nNarrow canonical substitution boundary for the existing OLA-030 production\ngraph.\n\nPurpose:\n- accept the existing OLA-030 production persistence router\n- accept the existing OLA-030 production_cycle_callable\n- construct OLA-048 exactly once\n- return the exact persistence router replacement for BOTH:\n    OracleLiveReadOnlyAcquisitionRuntime\n    OraclePostgreSQLShadowAcquisitionCycleOrchestrator (OLA-017)\n- return the exact cycle callable replacement for:\n    ShadowCycleRunnerBinding\n- preserve all unrelated OLA-030 graph components unchanged\n- preserve the original production router and cycle callable by identity\n\nNo scheduler kwargs changes.\nNo scheduler result projection changes.\nNo intelligence interpretation.\nNo signal scoring.\nNo alerts.\nNo Q Series handoff.\nNo execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom typing import Any, Callable, Mapping\n\nfrom .oracle_live_shadow_lineage_graph_binding_contract import (\n    OracleLiveShadowLineageGraphBindingContract,\n)\n\n\nSCHEMA_VERSION = "OLA-049"\nENGINE_ID = "OLA-049"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass OLA030LineageGraphIntegrationAdapterContractError(ValueError):\n    """Raised when OLA-049 integration input is malformed."""\n\n\nclass OLA030LineageGraphIntegrationAdapterInvariantError(RuntimeError):\n    """Raised when permanent OLA-049 invariants are violated."""\n\n\n@dataclass(frozen=True, slots=True)\nclass OLA030LineageGraphIntegrationBindings:\n    schema_version: str\n    engine_id: str\n    runtime_persistence_router: Any\n    ola017_persistence_router: Any\n    shadow_cycle_runner_callable: Callable[..., Any]\n    graph_binding: OracleLiveShadowLineageGraphBindingContract\n    original_persistence_router_preserved: bool\n    original_cycle_callable_preserved: bool\n    runtime_and_ola017_same_router: bool\n    scheduler_callable_lineage_wrapped: bool\n    scheduler_kwargs_unchanged: bool\n    scheduler_results_unchanged: bool\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                "engine identity invariant violated"\n            )\n\n        if (\n            self.runtime_persistence_router\n            is not self.ola017_persistence_router\n        ):\n            raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                "runtime and OLA-017 must share the same staged router"\n            )\n\n        required = (\n            self.original_persistence_router_preserved,\n            self.original_cycle_callable_preserved,\n            self.runtime_and_ola017_same_router,\n            self.scheduler_callable_lineage_wrapped,\n            self.scheduler_kwargs_unchanged,\n            self.scheduler_results_unchanged,\n        )\n\n        if required != (\n            True,\n            True,\n            True,\n            True,\n            True,\n            True,\n        ):\n            raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                "OLA-049 integration binding invariant violated"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                "OLA-049 read-only authority invariants violated"\n            )\n\n\nclass OracleOLA030LineageGraphIntegrationAdapter:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        production_persistence_router: Any,\n        production_cycle_callable: Callable[..., Any],\n    ) -> None:\n        route_batch = getattr(\n            production_persistence_router,\n            "route_batch",\n            None,\n        )\n\n        if not callable(route_batch):\n            raise OLA030LineageGraphIntegrationAdapterContractError(\n                "production_persistence_router must expose callable route_batch"\n            )\n\n        if not callable(production_cycle_callable):\n            raise OLA030LineageGraphIntegrationAdapterContractError(\n                "production_cycle_callable must be callable"\n            )\n\n        self._original_persistence_router = (\n            production_persistence_router\n        )\n        self._original_cycle_callable = (\n            production_cycle_callable\n        )\n\n        self._graph_binding = (\n            OracleLiveShadowLineageGraphBindingContract(\n                production_persistence_router=(\n                    production_persistence_router\n                ),\n                production_scheduler_cycle_callable=(\n                    production_cycle_callable\n                ),\n            )\n        )\n\n        self._bindings = OLA030LineageGraphIntegrationBindings(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            runtime_persistence_router=(\n                self._graph_binding.runtime_persistence_router\n            ),\n            ola017_persistence_router=(\n                self._graph_binding.ola017_persistence_router\n            ),\n            shadow_cycle_runner_callable=(\n                self._graph_binding.shadow_cycle_runner_callable\n            ),\n            graph_binding=self._graph_binding,\n            original_persistence_router_preserved=(\n                self._graph_binding.production_persistence_router\n                is production_persistence_router\n            ),\n            original_cycle_callable_preserved=(\n                self._graph_binding.production_scheduler_cycle_callable\n                is production_cycle_callable\n            ),\n            runtime_and_ola017_same_router=(\n                self._graph_binding.runtime_persistence_router\n                is self._graph_binding.ola017_persistence_router\n            ),\n            scheduler_callable_lineage_wrapped=(\n                self._graph_binding.shadow_cycle_runner_callable\n                is self._graph_binding.composition.scheduler_adapter\n            ),\n            scheduler_kwargs_unchanged=True,\n            scheduler_results_unchanged=True,\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n        )\n\n        self._bindings.assert_invariants()\n\n    @property\n    def bindings(\n        self,\n    ) -> OLA030LineageGraphIntegrationBindings:\n        return self._bindings\n\n    @property\n    def graph_binding(\n        self,\n    ) -> OracleLiveShadowLineageGraphBindingContract:\n        return self._graph_binding\n\n    def apply_to_graph_components(\n        self,\n        *,\n        graph_components: Mapping[str, Any],\n    ) -> dict[str, Any]:\n        if not isinstance(graph_components, Mapping):\n            raise OLA030LineageGraphIntegrationAdapterContractError(\n                "graph_components must be a mapping"\n            )\n\n        result = dict(graph_components)\n\n        protected_keys = {\n            "runtime_persistence_router",\n            "ola017_persistence_router",\n            "shadow_cycle_runner_callable",\n        }\n\n        for key in protected_keys:\n            if key in result:\n                raise OLA030LineageGraphIntegrationAdapterContractError(\n                    f"graph_components already contains protected key: {key}"\n                )\n\n        result["runtime_persistence_router"] = (\n            self._bindings.runtime_persistence_router\n        )\n        result["ola017_persistence_router"] = (\n            self._bindings.ola017_persistence_router\n        )\n        result["shadow_cycle_runner_callable"] = (\n            self._bindings.shadow_cycle_runner_callable\n        )\n\n        for key, value in graph_components.items():\n            if result[key] is not value:\n                raise OLA030LineageGraphIntegrationAdapterInvariantError(\n                    f"unrelated graph component was mutated: {key}"\n                )\n\n        return result\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_ola030_lineage_graph_integration_adapter import (\n    OLA030LineageGraphIntegrationAdapterContractError,\n    OracleOLA030LineageGraphIntegrationAdapter,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    ObservationRoutingEvidence,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 15, 0, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 15, 0, 0, 15, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 15, 0, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=batch_id,\n    )\n\n\ndef build_cohort(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.049.{cycle_number}"\n\n    return tuple(\n        build_observation(\n            market_id=f"KXTEST-OLA030-INTEGRATION-{index}",\n            frame_id=f"{cycle_number}-{index}",\n            batch_id=batch_id,\n            yes_ask=(\n                "0.9500"\n                if changed_market\n                == f"KXTEST-OLA030-INTEGRATION-{index}"\n                else "0.6140"\n            ),\n        )\n        for index in range(1, 6)\n    )\n\n\nclass FakeProductionPersistenceRouter:\n    def __init__(self):\n        self.batch_calls = 0\n\n    def route_batch(self, observations, routed_at):\n        self.batch_calls += 1\n\n        return tuple(\n            ObservationRoutingEvidence.create(\n                observation_id=observation.observation_id,\n                routed_at=routed_at,\n                accepted=True,\n                route_id="fake.ola.049.persistence",\n                metadata={"test": "OLA-049"},\n            )\n            for observation in observations\n        )\n\n    def __call__(self, observation, routed_at):\n        return ObservationRoutingEvidence.create(\n            observation_id=observation.observation_id,\n            routed_at=routed_at,\n            accepted=True,\n            route_id="fake.ola.049.persistence.single",\n            metadata={"test": "OLA-049"},\n        )\n\n\nclass FakeProductionCycleCallable:\n    def __init__(self):\n        self.call_count = 0\n        self.last_kwargs = None\n\n    def __call__(self, **kwargs):\n        self.call_count += 1\n        self.last_kwargs = dict(kwargs)\n\n        return {\n            "schema_version": "OLA-017",\n            "engine_id": "OLA-017",\n            "cycle_status": "completed",\n            "canonical_count": 5,\n            "postgresql_routing_record_delta": 5,\n            "read_only": True,\n            "execution_allowed": False,\n            "projected_by": "ola030-existing-cycle-callable",\n            "kwargs_echo": dict(kwargs),\n        }\n\n\ndef build_adapter():\n    persistence_router = FakeProductionPersistenceRouter()\n    cycle_callable = FakeProductionCycleCallable()\n\n    adapter = OracleOLA030LineageGraphIntegrationAdapter(\n        production_persistence_router=persistence_router,\n        production_cycle_callable=cycle_callable,\n    )\n\n    return adapter, persistence_router, cycle_callable\n\n\ndef run_binding_identity_test():\n    adapter, persistence_router, cycle_callable = build_adapter()\n    bindings = adapter.bindings\n\n    assert bindings.schema_version == "OLA-049"\n    assert bindings.engine_id == "OLA-049"\n    assert (\n        bindings.runtime_persistence_router\n        is bindings.ola017_persistence_router\n    )\n    assert (\n        adapter.graph_binding.production_persistence_router\n        is persistence_router\n    )\n    assert (\n        adapter.graph_binding.production_scheduler_cycle_callable\n        is cycle_callable\n    )\n    assert (\n        bindings.shadow_cycle_runner_callable\n        is adapter.graph_binding.shadow_cycle_runner_callable\n    )\n\n    return adapter\n\n\ndef run_graph_component_preservation_test():\n    adapter = run_binding_identity_test()\n\n    sentinel_runtime = object()\n    sentinel_scheduler = object()\n    sentinel_runner = object()\n\n    original = {\n        "runtime_root": sentinel_runtime,\n        "scheduler": sentinel_scheduler,\n        "runner": sentinel_runner,\n    }\n\n    integrated = adapter.apply_to_graph_components(\n        graph_components=original\n    )\n\n    assert integrated["runtime_root"] is sentinel_runtime\n    assert integrated["scheduler"] is sentinel_scheduler\n    assert integrated["runner"] is sentinel_runner\n    assert (\n        integrated["runtime_persistence_router"]\n        is adapter.bindings.runtime_persistence_router\n    )\n    assert (\n        integrated["ola017_persistence_router"]\n        is adapter.bindings.ola017_persistence_router\n    )\n    assert (\n        integrated["shadow_cycle_runner_callable"]\n        is adapter.bindings.shadow_cycle_runner_callable\n    )\n\n    return adapter\n\n\ndef run_three_cycle_integration_test():\n    adapter = run_graph_component_preservation_test()\n    bindings = adapter.bindings\n    receipts = []\n\n    for cycle_number, observed_at, changed_market in (\n        (1, T1, None),\n        (2, T2, None),\n        (\n            3,\n            T3,\n            "KXTEST-OLA030-INTEGRATION-4",\n        ),\n    ):\n        bindings.runtime_persistence_router.route_batch(\n            build_cohort(\n                cycle_number=cycle_number,\n                changed_market=changed_market,\n            ),\n            observed_at,\n        )\n\n        result = bindings.shadow_cycle_runner_callable(\n            cycle_completed_at=observed_at,\n            cycle_kwargs={\n                "cycle": cycle_number,\n                "ola030": True,\n            },\n        )\n\n        assert result["projected_by"] == (\n            "ola030-existing-cycle-callable"\n        )\n        assert result["kwargs_echo"] == {\n            "cycle": cycle_number,\n            "ola030": True,\n        }\n\n        receipts.append(\n            bindings\n            .shadow_cycle_runner_callable\n            .last_receipt\n        )\n\n    assert (\n        receipts[0]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 5\n    )\n    assert (\n        receipts[1]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 10\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .lineage_record_count_after\n        == 15\n    )\n    assert (\n        receipts[2]\n        .lineage_completion_receipt\n        .lineage_wiring_receipt\n        .transition_count\n        == 1\n    )\n\n    return adapter, receipts\n\n\ndef run_protected_key_fail_closed_test():\n    adapter = run_binding_identity_test()\n\n    try:\n        adapter.apply_to_graph_components(\n            graph_components={\n                "runtime_persistence_router": object(),\n            }\n        )\n        raise AssertionError(\n            "protected integration key collision must fail closed"\n        )\n    except OLA030LineageGraphIntegrationAdapterContractError:\n        pass\n\n\ndef run_deterministic_integration_replay_test():\n    def execute():\n        adapter, _, _ = build_adapter()\n        bindings = adapter.bindings\n        receipts = []\n\n        for cycle_number, observed_at, changed_market in (\n            (1, T1, None),\n            (2, T2, None),\n            (\n                3,\n                T3,\n                "KXTEST-OLA030-INTEGRATION-2",\n            ),\n        ):\n            bindings.ola017_persistence_router.route_batch(\n                build_cohort(\n                    cycle_number=cycle_number,\n                    changed_market=changed_market,\n                ),\n                observed_at,\n            )\n\n            bindings.shadow_cycle_runner_callable(\n                cycle_completed_at=observed_at,\n                cycle_kwargs={"cycle": cycle_number},\n            )\n\n            receipts.append(\n                bindings\n                .shadow_cycle_runner_callable\n                .last_receipt\n            )\n\n        records = (\n            adapter\n            .graph_binding\n            .composition\n            .production_wiring\n            .lineage_bridge\n            .coordinator\n            .lineage_cycle_bridge\n            .batch_router\n            .bridge\n            .ledger\n            .records()\n        )\n\n        return tuple(receipts), records\n\n    first_receipts, first_records = execute()\n    second_receipts, second_records = execute()\n\n    assert first_receipts == second_receipts\n    assert first_records == second_records\n\n    return first_receipts, first_records\n\n\ndef main():\n    adapter, receipts = run_three_cycle_integration_test()\n\n    run_protected_key_fail_closed_test()\n\n    replay_receipts, replay_records = (\n        run_deterministic_integration_replay_test()\n    )\n\n    bindings = adapter.bindings\n\n    result = {\n        "schema_version": bindings.schema_version,\n        "engine_id": bindings.engine_id,\n        "status": "passed",\n        "ola_048_graph_binding_consumed": True,\n        "original_production_persistence_router_preserved": True,\n        "original_production_cycle_callable_preserved": True,\n        "runtime_persistence_router_substitution_ready": True,\n        "ola017_persistence_router_substitution_ready": True,\n        "runtime_and_ola017_same_staged_router": True,\n        "shadow_cycle_runner_callable_substitution_ready": True,\n        "unrelated_graph_components_preserved_by_identity": True,\n        "protected_integration_key_collision_fails_closed": True,\n        "first_cycle_lineage_record_count": (\n            receipts[0]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "second_cycle_lineage_record_count": (\n            receipts[1]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_lineage_record_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .lineage_record_count_after\n        ),\n        "third_cycle_transition_count": (\n            receipts[2]\n            .lineage_completion_receipt\n            .lineage_wiring_receipt\n            .transition_count\n        ),\n        "scheduler_kwargs_unchanged": True,\n        "scheduler_results_unchanged": True,\n        "deterministic_ola030_integration_replay_valid": (\n            len(replay_receipts) == 3\n            and len(replay_records) == 15\n        ),\n        "ready_for_ola030_full_replacement": True,\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": bindings.read_only,\n        "execution_allowed": bindings.execution_allowed,\n        "execution_adapter_resolved": (\n            bindings.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            bindings.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            bindings.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            bindings.order_placement_allowed\n        ),\n        "funds_moved": bindings.funds_moved,\n        "portfolio_mutated": bindings.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-049 Oracle OLA-030 Lineage "\n        "Graph Integration Adapter"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(
        source,
        encoding="utf-8",
        newline="\n",
    )
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-049 INSTALLER")
    print(" OLA-030 LINEAGE GRAPH INTEGRATION")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-049 Oracle OLA-030 Lineage "
        "Graph Integration Adapter installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_049_oracle_ola030_lineage_"
        "graph_integration_adapter.py"
    )


if __name__ == "__main__":
    main()
